    /// # Errors
    /// A different field contract, Arrow failure or row-count overflow.
    pub fn append_view(
        &mut self,
        view: &ReferenceRuleUnnestView<'_>,
    ) -> Result<(), crate::RelationError> {
        self.columns.append_batch(view.batch())
    }
